_n = [0]
def Q(en, ar, right, wrong, **k):
    ans = LET[_n[0]]; _n[0] += 1
    opts = list(wrong); opts.insert("abcd".index(ans), right)
    return dict(en=en, ar=ar, options=[list(o) for o in opts], answer=ans, **k)

